#!/usr/bin/env python3
"""Tables and plot data of the extended technical report.

Writes generated/report/tables/*.tex and generated/report/data/*.csv; never
touches generated/paper/. No number is typed by hand. A cell is either

  * a macro of generated/paper/results-macros.tex (generated by
    make_macros.py from the CSVs); the macro must exist, or the script
    stops, or
  * computed here from results/*.csv, using only rows that are
    OPTIMAL and VERIFY OK (or UNSAT), or
  * input data read from the safedse data files (catalog, tactic table, cost
    profiles, platforms), which are inputs, not measurements.

    python3 make_report.py
"""
from __future__ import annotations

import csv
import re
import statistics
import sys
import xml.etree.ElementTree as ET
from collections import Counter, defaultdict
from pathlib import Path

import yaml

import make_catalogue_table as mct

sys.path.insert(0, str(Path(__file__).resolve().parent))
from paths import PAPER_OUT, REPORT_OUT, ROOT  # noqa: E402

RESULTS = ROOT / "results"
REPORT = REPORT_OUT
TABLES = REPORT / "tables"
DATA = REPORT / "data"
MACROS = PAPER_OUT / "results-macros.tex"
SAFEDSE = mct.SAFEDSE
HEADER = (f"% GENERATED by {Path(__file__).name} (SafeDSE-experiments) -- do "
          f"not edit.\n")

_macros = dict(re.findall(r"\\newcommand\{\\res([A-Za-z]+)\}\{([^}]*)\}",
                          MACROS.read_text()))


def M(name: str, optional: bool = False) -> str:
    """Reference to \\res<name>; stops on a missing macro unless optional."""
    if name not in _macros:
        if optional:
            return "--"
        sys.exit(f"macro \\res{name} does not exist in {MACROS.name}")
    return f"\\res{name}{{}}"


def has(name: str) -> bool:
    return name in _macros


def read_csv(name: str) -> list[dict]:
    with (RESULTS / name).open(newline="") as f:
        return list(csv.DictReader(f))


def ok(r: dict) -> bool:
    return r.get("status") == "OPTIMAL" and r.get("verify_ok") == "True"


def write(name: str, body: list[str], sources: str) -> None:
    TABLES.mkdir(parents=True, exist_ok=True)
    (TABLES / name).write_text(HEADER + f"% from {sources}\n" +
                               "\n".join(body) + "\n")
    print(f"wrote report/tables/{name}")


def code(s: str) -> str:
    return r"\code{" + s.replace("_", r"\_") + "}"


def tex(s: str) -> str:
    return (s.replace("\\", "").replace("_", r"\_").replace("%", r"\%")
            .replace("&", r"\&").replace("#", r"\#"))


INSTANCES = ["p_rasta", "f_random_hw", "d_random_hw", "d_systematic_sw",
             "f_sw3", "f_both3", "c_pat", "pc_sobel", "v_nvp"]
FLOWS = ["SL", "PFmin", "PFmax", "PFlight", "PFcheap", "NP"]
FLOW_TEX = {"joint": "Joint", "SL": "SL", "PFmin": r"PF$^{-}$",
            "PFmax": r"PF$^{+}$", "PFlight": r"PF$^{t}$",
            "PFcheap": r"PF$^{c}$", "NP": "NP"}
FLOW_MAC = {"SL": "SL", "PFmin": "PFMin", "PFmax": "PFMax",
            "PFlight": "PFLight", "PFcheap": "PFCheap", "NP": "NP"}
FACTORS = ["1.00", "1.10", "1.25", "1.50", "2.00"]
FAC_MAC = {"1.00": "Hundred", "1.10": "HundredTen",
           "1.25": "HundredTwentyFive", "1.50": "HundredFifty",
           "2.00": "TwoHundred"}
VAR_MAC = {"base": "Base", "tok2": "TokTwo", "chk10": "ChkTen",
           "chk50": "ChkFifty"}
VAR_TEX = {"base": "base", "tok2": r"\code{tok2}", "chk10": r"\code{chk10}",
           "chk50": r"\code{chk50}"}
NUM = {"1": "One", "2": "Two", "4": "Four", "8": "Eight", "16": "Sixteen"}
PROFILES = ["myklebust2015", "klosterman", "klosterman_low", "do178b"]
PROFILE_TEX = {"myklebust2015": "Myklebust et al.", "klosterman": "Klosterman",
               "klosterman_low": "Klosterman (lower row)",
               "do178b": "DO-178B"}


# ---------------------------------------------------------------------------
# Inputs: catalog, scenarios, tactics, cost profiles, platforms
# ---------------------------------------------------------------------------
def _catalog() -> list[tuple[dict, str]]:
    pats = yaml.safe_load(mct.MAIN.read_text())["patterns"]
    demo = {p["id"]: p for p in yaml.safe_load(mct.DEMO.read_text())["patterns"]}
    return [(p, "") for p in pats] + [(demo[i], r"$^\dagger$")
                                      for i in mct.EXTRA]


def _wcet_type(c: dict) -> str:
    w = c.get("wcet_type", "")
    return "full" if w == "<owner>" else w.split("_")[0]


def tab_catalog_full() -> None:
    rows = _catalog()
    body = [
        r"\setlength{\tabcolsep}{3pt}",
        r"\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}l"
        r" >{\raggedright\arraybackslash}p{1.15in}"
        r" >{\raggedright\arraybackslash}p{1.3in}"
        r" >{\raggedright\arraybackslash}p{0.85in} l c c"
        r" >{\raggedright\arraybackslash}p{1.1in}@{}}",
        r"\toprule",
        r"Pattern & Components (WCET, $\Delta$SIL) & Edges (tokens) & "
        r"Inputs to / output from & Failure & Rec. & Mult. & Tactics \\",
        r"\midrule",
    ]
    tac_abbr = {"Sanity Check": "SaC", "Condition Monitoring": "CM",
                "Comparison": "Cmp", "Replication Redundancy": "RR",
                "Diverse Redundancy": "DR", "Voting": "Vot",
                "Override": "Ovr", "Repair": "Rep"}
    for p, mark in rows:
        comps = ", ".join(
            f"${mct.sym(c['role'])}$ ({_wcet_type(c)}, "
            f"{'$-' + str(c['sil_offset']) + '$' if c.get('sil_offset') else '0'})"
            for c in p["components"]) or "--"
        edges = ", ".join(
            f"${mct.sym(e['from'])}\\!\\to\\!{mct.sym(e['to'])}$ ({e['tokens']})"
            for e in p["edges"]) or "--"
        fan = p.get("input_fanout") or []
        io = (("$" + ",".join(mct.sym(r) for r in fan) + "$" if fan else "--")
              + " / " + (f"${mct.sym(p['output_from'])}$"
                         if p.get("output_from") else "--"))
        mult = p.get("dev_cost_multiplier") or {}
        mdiv = p.get("dev_cost_multiplier_diverse") or {}
        mvals = sorted({float(v) for v in mult.values()})
        mtex = "/".join(f"{v:g}" for v in mvals) if mvals else "--"
        if mdiv:
            mtex += " (" + "/".join(f"{float(v):g}" for v in mdiv.values()) + r"$^{d}$)"
        tacs = ", ".join(tac_abbr[t] for t in p.get("tactics", [])) or "--"
        body.append(f"{mct.NAME[p['id']]}{mark} & {comps} & {edges} & {io} & "
                    f"{p.get('failure_mode', '--')} & "
                    f"{p.get('recurring_cost_units', 0)} & {mtex} & {tacs} \\\\")
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\textwidth}{\scriptsize Roles as in "
             r"\cref{tab:catalogue}. WCET: \emph{full}, the owner's WCET "
             r"(a replica); \emph{checker} or \emph{voter}, the component's "
             r"own WCET entry. $\Delta$SIL: the catalog's \code{sil\_offset}, "
             r"the number of levels by which the doer may be developed below "
             r"the actor's SIL; the model does not use it "
             r"(\cref{sec:discussion}). Edges: from, to, and initial tokens. "
             r"Inputs to: components that receive copies of the owner's input "
             r"channels; output from: the role whose output leaves the "
             r"pattern. Failure: failure mode of the protected function. Rec.: "
             r"recurring cost units. Mult.: development-cost multipliers per "
             r"component in the catalog ($^{d}$when the pattern places the "
             r"component \code{DIVERSE}); read but not priced by the model. "
             r"Tactics after Preschern et al.: SaC sanity check, Cmp "
             r"comparison, RR replication redundancy, DR diverse redundancy, "
             r"Vot voting, Rep repair. $^\dagger$Separate catalog.}"]
    write("tab-catalog-full.tex", body, "safedse data/patterns*.yaml")


def tab_scenarios() -> None:
    body = [
        r"\setlength{\tabcolsep}{3pt}",
        r"\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}l l c l"
        r" >{\raggedright\arraybackslash}p{4.05in}@{}}",
        r"\toprule",
        r"Pattern & Scen. & Covers & Tactics & General scenario (catalog text) \\",
        r"\midrule",
    ]
    for p, mark in _catalog():
        sc = p.get("scenarios") or []
        for k, s in enumerate(sc):
            name = f"{mct.NAME[p['id']]}{mark}" if k == 0 else ""
            cov = mct.FAULT.get(s.get("covers"), "--")
            body.append(f"{name} & {s['id']} & {cov} & "
                        f"{', '.join(s.get('tactics', []))} & "
                        f"{tex(' '.join(s['text'].split()))} \\\\")
        if sc:
            body.append(r"\addlinespace[1pt]")
    if body[-1].startswith(r"\addlinespace"):
        body.pop()
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\textwidth}{\scriptsize Covers: the fault "
             r"class a scenario needs (H random hardware, S systematic); a "
             r"scenario outside the fault model becomes an undeveloped goal "
             r"with the fault model as the reason. "
             r"--: in scope under every fault model. \code{none} has no "
             r"scenario. $^\dagger$Separate catalog.}"]
    write("tab-scenarios.tex", body, "safedse data/patterns*.yaml")


def tab_tactics() -> None:
    tac = yaml.safe_load((SAFEDSE / "data" / "gsn_tactics.yaml").read_text())
    used: dict[str, list[str]] = defaultdict(list)
    for p, _ in _catalog():
        for t in p.get("tactics", []):
            used[t].append(mct.NAME[p["id"]])
    body = [
        r"\setlength{\tabcolsep}{3pt}",
        r"\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}l l"
        r" >{\raggedright\arraybackslash}p{2.1in} l"
        r" >{\raggedright\arraybackslash}p{1.5in}@{}}",
        r"\toprule",
        r"Tactic & Category & IEC 61508-7 methods & Relations & "
        r"Patterns using it \\",
        r"\midrule",
    ]
    for t in tac["tactics"]:
        meths = []
        for m in t["iec61508_methods"]:
            m = m.replace("IEC 61508-7 ", "")
            meths.append(tex(m))
        rel = ", ".join(code(r) for r in t.get("deployment_relations", [])) or "--"
        pats = ", ".join(used.get(t["name"], [])) or "--"
        body.append(f"{t['name']} & {t['category']} & {'; '.join(meths)} & "
                    f"{rel} & {pats} \\\\")
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\textwidth}{\scriptsize Methods as listed "
             r"by Preschern et al.\ (annex clause of IEC~61508-7 and its "
             r"title). Relations: the placement relations whose verifier "
             r"records discharge the tactic's deployment precondition "
             r"(\code{deployment\_relations} of the tactic table); a tactic "
             r"without one is realized in the value domain and stays "
             r"undeveloped.}"]
    write("tab-tactics.tex", body, "safedse data/gsn_tactics.yaml")


def tab_profiles() -> None:
    files = [SAFEDSE / "data" / "cost_model.xml",
             ROOT / "variants" / "cost_model_klosterman_low.xml"]
    prof: dict[str, dict[int, int]] = {}
    base = None
    for f in files:
        root = ET.parse(f).getroot()
        for p in root.iter("profile"):
            prof[p.get("name")] = {int(s.get("level")): int(s.get("multiplier"))
                                   for s in p.iter("sil")}
        b = root.find("baseline")
        if b is not None and base is None:
            base = b.get("default")
    body = [r"\setlength{\tabcolsep}{4pt}",
            r"\begin{tabular*}{\columnwidth}{@{\extracolsep{\fill}}l rrrrr@{}}",
            r"\toprule",
            r"Profile & SIL~0 & 1 & 2 & 3 & 4 \\", r"\midrule"]
    for name in PROFILES:
        k = prof[name]
        body.append(f"{PROFILE_TEX[name]} & " +
                    " & ".join(f"{k[s] / 100:.2f}" for s in range(5)) + r" \\")
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\columnwidth}{\scriptsize Multiplier $k(s)$ "
             r"of the baseline development cost (" + str(base) + r" units "
             r"per node). SIL~0 and SIL~4 are extrapolated. Lower row: "
             r"Klosterman's ASIL~C row for SIL~3, used only in the price "
             r"sweep of \cref{sec:eval-rq4}.}"]
    write("tab-profiles.tex", body,
          "safedse data/cost_model.xml, variants/"
          "cost_model_klosterman_low.xml")


