def tab_platforms() -> None:
    body = [r"\setlength{\tabcolsep}{3pt}",
            r"\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}l l l c c r"
            r" >{\raggedright\arraybackslash}p{1.55in} c c r@{}}",
            r"\toprule",
            r"Platform file & Card & Core type & Cores & Max. & Card price & "
            r"Modes (cycle factor, core price) & $\silmax$ & Part. & Memory \\",
            r"\midrule"]
    for stem, use in PLATFORMS:
        root = ET.parse(SAFEDSE / "data" / "platform" / f"{stem}.xml").getroot()
        first = True
        for t in root.iter("fcr_template"):
            for pr in t.iter("processor"):
                modes = "; ".join(f"{m.get('name')} ({m.get('cycle')}, "
                                  f"{m.get('monetary')})"
                                  for m in pr.iter("mode"))
                part = ("yes, " + pr.get("partition_cost")
                        if pr.get("partitionable") == "true" else "no")
                body.append(
                    f"{code(stem + '.xml') if first else ''} & {t.get('name')} "
                    f"& {pr.get('model')} & {pr.get('count')} & "
                    f"{t.get('max_instances')} & {t.get('monetary')} & {modes} & "
                    f"{pr.get('max_sil')} & {part} & {pr.get('mem')} \\\\")
                first = False
        bus = root.find(".//TDMA_bus")
        if bus is not None and stem == "mixed":
            tdma = (f"{bus.get('tdma_slots')} slots, at most "
                    f"{bus.get('maxSlotsPerProc')} per core")
        body.append(r"\addlinespace[1pt]")
    body.pop()
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\textwidth}{\scriptsize Used by: " +
             "; ".join(f"{code(s + '.xml')}: {u}" for s, u in PLATFORMS) +
             r". Max.: cards the front-end may instantiate. Cycle factor: "
             r"multiplier of the nominal execution time in that mode. "
             r"Part.: certified partitioning and its cost per partitioned core. "
             r"TDMA bus of the card platforms: " + tdma + r". Prices in cost "
             r"units; they are illustrative.}"]
    write("tab-platforms.tex", body, "safedse data/platform/*.xml")


