def tab_patcons() -> None:
    rows = read_csv("e4_patcons.csv")
    by = defaultdict(dict)
    for r in rows:
        by[(r["instance"], int(r["k"]))][r["baseline"]] = r
    body = [r"\setlength{\tabcolsep}{3pt}",
            r"\begin{tabular*}{\columnwidth}{@{\extracolsep{\fill}}l c c r r c@{}}",
            r"\toprule",
            r"Instance & Cores & $k$ & Joint & Promotion & NP \\", r"\midrule"]
    last = None
    for (inst, k) in sorted(by, key=lambda x: (INSTANCES.index(x[0])
                                                if x[0] in INSTANCES else 99,
                                                -x[1])):
        d = by[(inst, k)]
        j = d.get("joint")
        np_ = d.get("NP")
        if j is None:
            continue
        if ok(j):
            jc, pr = j["total_cost"], j["promotion_cost"]
        elif j["status"] == "UNSAT":
            jc, pr = r"$\infty$", "--"
        else:
            jc, pr = "t/o", "--"     # time limit, not verified
        if np_ is None:
            nc = "--"
        elif np_["status"] == "UNSAT":
            nc = r"$\infty$"
        elif ok(np_):
            nc = np_["total_cost"]
        else:
            nc = "t/o"
        name = code(inst) if inst != last else ""
        cores = j["cores_opt"] if inst != last else ""
        body.append(f"{name} & {cores} & {k} & {jc} & {pr} & {nc} \\\\")
        last = inst
    body += [r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\columnwidth}{\scriptsize Cores: of the "
             r"unbounded joint optimum. $k$: at most $k$ cores. Joint: proven "
             r"minimum of $C_{\mathrm{tot}}$, Promotion: its $C_{\mathrm{pro}}$; "
             r"NP: the no-promotion flow. $\infty$: proven infeasible; t/o: "
             r"time limit, incumbent not verified (\cref{sec:discussion}).}"]
    write("tab-patcons.tex", body, "e4_patcons.csv")


