def data_flat() -> None:
    rows = [r for r in read_csv("e3_flat.csv")
            if r["set"] == "rq3" and r["stage"] == "THROUGHPUT"
            and r["status"] == "OK"]
    by = defaultdict(list)
    for r in rows:
        if r["tag"].startswith("actorsweep"):
            by[int(r["param"])].append(r)
    DATA.mkdir(parents=True, exist_ok=True)
    with (DATA / "flat.csv").open("w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["actors", "seconds", "mb", "rss_mb", "vars_k"])
        for n in sorted(by):
            g = by[n]
            w.writerow([n,
                        f"{statistics.median(float(r['seconds']) for r in g):.2f}",
                        f"{statistics.median(int(r['fzn_bytes']) for r in g) / 1e6:.1f}",
                        f"{statistics.median(float(r['max_rss_mb']) for r in g):.0f}",
                        f"{statistics.median(int(r['fzn_vars']) for r in g) / 1e3:.1f}"])
    print("wrote report/data/flat.csv")


