def tab_mut_model() -> None:
    rows = read_csv("e6_mut.csv")
    ex = {(o["part"], o["instance"], o["operator"], o["mutant"]):
          o["exact_status"] for o in read_csv("e6_oracle.csv")}
    fam = defaultdict(lambda: {"runs": 0, "man": 0, "art": 0, "cur": 0})
    for r in rows:
        if r["part"] != "model":
            continue
        k = (r["part"], r["instance"], r["operator"], r["mutant"])
        man = r["model_status"] not in ("", "N/A") and ex.get(k) in ("UNSAT",
                                                                       "COSTS")
        f = fam[r["operator"]]
        if r["verifier"] == "safedse":
            f["runs"] += 1
            f["man"] += man
            f["art"] += man and r["verify_ok"] == "False"
        elif r["verifier"] == "artifact":
            f["cur"] += man and r["verify_ok"] == "False"
    if set(fam) - set(MUT_FAM):
        sys.exit(f"unknown model-mutant families: {set(fam) - set(MUT_FAM)}")
    tot = {k: sum(f[k] for f in fam.values()) for k in ("runs", "man", "art", "cur")}
    if (tot["man"] != int(_macros["MutModelManifested"])
            or tot["art"] != int(_macros["MutModelRejectedArt"])
            or tot["cur"] != int(_macros["MutModelRejectedCur"])
            or tot["runs"] != int(_macros["MutModelRuns"])):
        sys.exit(f"model-mutant totals differ from the macros: {tot}")
    body = [r"\setlength{\tabcolsep}{3pt}",
            r"\begin{tabular*}{\columnwidth}{@{\extracolsep{\fill}}l c c c c@{}}",
            r"\toprule",
            r"Constraint family removed & Runs & Viol. & First & Current \\",
            r"\midrule"]
    for op in MUT_FAM:
        if op not in fam:
            continue
        f = fam[op]
        body.append(f"{MUT_FAM[op]} & {f['runs']} & {f['man']} & {f['art']} & "
                    f"{f['cur']} \\\\")
    body += [r"\midrule",
             f"all & {M('MutModelRuns')} & {M('MutModelManifested')} & "
             f"{M('MutModelRejectedArt')} & {M('MutModelRejectedCur')} \\\\",
             r"\bottomrule", r"\end{tabular*}", "",
             r"\vspace{2pt}\parbox{\columnwidth}{\scriptsize One copy of the "
             r"model per family, the family disabled; optima of the "
             r"\resMutSolInstances{} instances (TOTALCOST, 120\,s). Viol.: "
             r"solutions that violate the original model (exact variant B as "
             r"the oracle). First / Current: violating solutions rejected by "
             r"the first and the current verifier.}"]
    write("tab-mut-model.tex", body, "e6_mut.csv, e6_oracle.csv")


def main() -> int:
    tab_catalog_full()
    tab_scenarios()
    tab_tactics()
    tab_profiles()
    tab_platforms()
    tab_pipe()
    tab_xsolver()
    tab_rq2_nobound()
    tab_rq2_all()
    tab_rq2_thr()
    tab_pfchoice()
    tab_multi()
    tab_patcons()
    tab_modelext()
    tab_modelext_flows()
    tab_scal()
    tab_price()
    tab_comm()
    tab_gsn()
    tab_mut_ops()
    tab_mut_model()
    data_flat()
    data_thr()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
